def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    def get_line():
        nonlocal idx
        if idx < len(lines):
            line = lines[idx]
            idx += 1
            return line.strip() if line.strip() else None
        return None

    # Read t (number of test cases)
    while lines and lines[0].strip() == '':
        idx += 1

    if idx >= len(lines):
        return ''

    t = int(get_line())

    results = []

    for _ in range(t):
        # Read n and m
        while idx < len(lines) and lines[idx].strip() == '':
            idx += 1
        if idx >= len(lines):
            break
        n, m = map(int, get_line().split())

        # Read matrix
        matrix = []
        for _ in range(n):
            while idx < len(lines) and lines[idx].strip() == '':
                idx += 1
            row = list(map(int, get_line().split()))
            matrix.append(row)

        # Check if any cell has non-zero value
        has_non_zero = False
        for i in range(n):
            for j in range(m):
                if matrix[i][j] > 0:
                    has_non_zero = True
                    break
            if has_non_zero:
                break

        # If there's at least one non-zero cell, Ashish wins. Otherwise Jeel wins.
        if has_non_zero:
            results.append("Ashish")
        else:
            results.append("Jeel")

    return '\n'.join(results)

import heapq
from collections import defaultdict

def solution(input_string):
    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    adjacency = defaultdict(list)

    for i in range(m):
        u_i, v_i, w_i = map(int, lines[i + 1].split())
        edges.append((u_i, v_i, w_i, i + 1))
        adjacency[u_i].append((v_i, w_i))
        adjacency[v_i].append((u_i, w_i))

    start_vertex = int(lines[m + 1])

    # Dijkstra's algorithm to find shortest distances from start_vertex
    dist = [-1] * (n + 1)
    dist[start_vertex] = 0
    pq = [(0, start_vertex)]

    while pq:
        d, u_i = heapq.heappop(pq)

        if dist[u_i] != -1 and d > dist[u_i]:
            continue

        for v_i, w_i in adjacency[u_i]:
            if dist[v_i] == -1 or d + w_i < dist[v_i]:
                dist[v_i] = d + w_i
                heapq.heappush(pq, (dist[v_i], v_i))

    # For each vertex (except start_vertex), select the edge that gives shortest path
    # and has minimum weight among candidates
    total_weight = 0
    selected_edges = []

    for v in range(1, n + 1):
        if v == start_vertex:
            continue

        if dist[v] == -1:
            continue

        min_edge_weight = float('inf')
        best_edge_index = -1

        for u_i, v_node, w_i, edge_index in edges:
            # Check if this edge can be part of shortest path to v_node
            if v_node == v and dist[v_node] == -1:
                continue

            # This edge connects some u_i to v_node (which is v)
            # Check if it satisfies the shortest path condition
            if v_node == v and dist[u_i] != -1 and dist[u_i] + w_i == dist[v]:
                if w_i < min_edge_weight:
                    min_edge_weight = w_i
                    best_edge_index = edge_index

    # Alternative approach: iterate through edges and pick for each vertex
    # For each vertex v != start, find edges (u, v) where dist[u] + w = dist[v]
    # Pick the one with minimum w

    for v in range(1, n + 1):
        if v == start_vertex:
            continue

        if dist[v] == -1:
            continue

        min_edge_weight = float('inf')
        best_edge_index = -1

        # Check all edges to v
        for u, target, edge_w, edge_idx in edges:
            if target == v and dist[u] != -1 and dist[u] + edge_w == dist[v]:
                if edge_w < min_edge_weight:
                    min_edge_weight = edge_w
                    best_edge_index = edge_idx

        if best_edge_index != -1:
            total_weight += min_edge_weight
            selected_edges.append(best_edge_index)

    return f"{total_weight}\n{' '.join(map(str, selected_edges))} "

