def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    competitors = []

    for i in range(1, n + 1):
        s, r = map(int, lines[i].split())
        competitors.append((s, r, i))  # store original index

    possible = [True] * n

    for i in range(n):
        si, ri, _ = competitors[i]
        for j in range(n):
            if i == j:
                continue
            sj, rj, _ = competitors[j]
            # If j dominates i (strictly better or equal in both), i can't beat j
            if sj >= si and rj >= ri and (sj > si or rj > ri):
                possible[i] = False
                break

    result = []
    for i in range(n):
        if possible[i]:
            result.append(str(competitors[i][2]))

    return " ".join(result) + "\n"

def solution(input_str):
    input_data = input_str.strip().split('\n')
    n = int(input_data[0])
    arr = list(map(int, input_data[1].split()))

    MOD = 1000000007

    # Find positions with -1
    available_positions = []  # 1-indexed positions where arr[i] == -1
    seen_values = set()

    for i in range(n):
        if arr[i] == -1:
            available_positions.append(i + 1)
        else:
            seen_values.add(arr[i])

    # Find available values (values 1 to n not in seen)
    available_values = []
    for v in range(1, n + 1):
        if v not in seen_values:
            available_values.append(v)

    m = len(available_values)

    # Check which available values are forbidden at which available positions
    # forbidden[i][v] = True if available_values[v] cannot go to available_positions[i]
    # (i.e., they create a fixed point)

    forbidden = [[False] * m for _ in range(m)]
    for i, pos in enumerate(available_positions):
        for j, val in enumerate(available_values):
            if pos == val and (i != 0 or j != 0):  # special case
                forbidden[i][j] = True

    # DP: count valid assignments
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(idx, count):
        if idx == m:
            return 1

        count = 0
        for j in range(count, m):
            if not forbidden[idx][j]:
                count = (count + dp(idx + 1, j + 1)) % MOD
        return count

    return "0"

