            u, v = map(int, lines[i].split())
            graph[u].append(v)
            graph[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            queue = deque([i])
            visited[i] = True
            while queue:
                node = queue.popleft()
                size += 1
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            if size > 0:
                component_sizes.append(size)

    if not component_sizes:
        return '-1\n'

    # Generate lucky numbers up to n using BFS
    lucky_numbers = []
