            queue.append(s + '4')
        if len(s) < 18 and int(s) * 10 <= n:
            queue.append(s + '7')

    # Sort lucky numbers
    lucky_numbers.sort()

    # DP to find min roads to achieve each sum
    # dp[sum] = min roads needed
    dp = {}

    # Start with individual components
    for size in component_sizes:
        dp[size] = min(dp.get(size, float('inf')), 0)

    # Try to merge components
    for lucky in lucky_numbers:
        # Find the minimum roads needed for this lucky sum
        for current_sum in range(lucky, 0, -1):
            if current_sum in dp and (lucky - current_sum) in dp:
                dp[current_sum] = min(dp.get(current_sum, float('inf')), 
                                     dp[current_sum] if current_sum < lucky else float('inf'))

    # Better approach: use set of achievable sums
    achievable = set()
    roads_needed = {}

    for size in component_sizes:
        achievable.add(size)
        if size not in roads_needed:
            roads_needed[size] = 0

    # Try merging
    for lucky in lucky_numbers:
        if lucky in achievable:
            roads = roads_needed.get(lucky, float('inf'))
            # Since we could have reached lucky with fewer merges
            # Actually, use min component size as the answer since any 2+ components need at least 1 road
            if len(achievable) > 0:
                min_roads = 1
            else:
                min_roads = 0
            break

    # Correct DP:
    achievable_sums = set()
    achievable_sums.add(0)
    min_roads = {}

    for size in component_sizes:
        achievable_sums.add(size)
        if size > 0:
            min_roads[size] = 0

    possible = set(component_sizes)
    possible.add(0)

    # Use DP with set tracking
    dp_dp = {}  # sum -> min roads

    for size in component_sizes:
        dp_dp[size] = 0

    # Try each lucky number
    for lucky in lucky_numbers:
        if lucky in dp_dp and dp_dp[lucky] != float('inf'):
            if lucky == max(possible):
                # Only 1 component needed
                ans = 0 if lucky in component_sizes else float('inf')
            else:
                # Need at least 2 components
                ans = float('inf')

    # Final DP approach
    from collections import defaultdict

    min_roads_for_sum = defaultdict(lambda: float('inf'))
    min_roads_for_sum[0] = 0

    for size in component_sizes:
        # Using this component alone
        if size not in min_roads_for_sum or min_roads_for_sum[size] > 0:
            min_roads_for_sum[size] = 0

    # Try merging
    possible_sums = set(component_sizes)

    best = float('inf')
    for lucky in lucky_numbers:
        if lucky in possible_sums and 1 <= lucky <= n:
            # count how many components needed
            # if lucky is in component_sizes, answer is 0
            # otherwise, need to merge multiple components
            if lucky in component_sizes:
                best = min(best, 0)
            else:
                best = min(best, 1)

    if best == float('inf'):
