def count_squares(grid, n, m):
    count = count_axis_aligned(grid, n, m)
    count += count_diagonal(grid, n, m)
    return count

def check_no_touching(grid, r1, c1, r2, c2, n, m):
    """Check no 1s touch the border of potential square by side or corner"""
    for i in range(max(r1 - 1, 0), min(r2 + 2, n)):
        for j in range(max(c1 - 1, 0), min(c2 + 2, m)):
            if i == r1 - 1 or i == r2 + 1 or j == c1 - 1 or j == c2 + 1:
                if grid[i][j] == '1':
                    return False
    return True

def check_diagonal_no_touching(grid, r_center, c_center, k, n, m):
    """Check no 1s touch the border of potential diamond by side or corner"""
    for i in range(max(r_center - k - 1, 0), min(r_center + k + 2, n)):
        for j in range(max(c_center - k - 1, 0), min(c_center + k + 2, m)):
            if (i == r_center - k - 1 or i == r_center + k + 1 or 
                j == c_center - k - 1 or j == c_center + k + 1):
                if grid[i][j] == '1':
                    return False
            # Also check corners of the bounding box
            if i == r_center - k - 1 and j == c_center - k - 1:
                if grid[i][j] == '1':
                    return False
            if i == r_center - k - 1 and j == c_center + k + 1:
                if grid[i][j] == '1':
                    return False
            if i == r_center + k + 1 and j == c_center - k - 1:
                if grid[i][j] == '1':
                    return False
            if i == r_center + k + 1 and j == c_center + k + 1:
                if grid[i][j] == '1':
                    return False
    return True

def count_axis_aligned(grid, n, m):
    count = 0
    for k in range(2, min(n, m)):
        for i in range(n - k):
            for j in range(m - k):
                # Check four corners are 1
                if (grid[i][j] == '1' and grid[i][j+k] == '1' and 
                    grid[i+k][j] == '1' and grid[i+k][j+k] == '1'):

                    # Check border is all 1s
                    top_ok = all(grid[i][c] == '1' for c in range(j, j+k+1))
                    bottom_ok = all(grid[i+k][c] == '1' for c in range(j, j+k+1))
                    left_ok = all(grid[r][j] == '1' for r in range(i, i+k+1))
                    right_ok = all(grid[r][j+k] == '1' for r in range(i, i+k+1))

                    if top_ok and bottom_ok and left_ok and right_ok:
                        # Check no foreign 1 touches
                        if check_no_touching(grid, i, j, i+k, j+k, n, m):
                            count += 1
    return count

def count_diagonal(grid, n, m):
    count = 0
    for r in range(2, n - 2):
        for c in range(2, m - 2):
            for k in range(1, min(n - r, m - c, r, c)):
                # Check four cardinal vertices are 1
                top = grid[r-k][c]
                right = grid[r][c-k]
                bottom = grid[r+k][c]
                left = grid[r][c+k]

                if top == '1' and right == '1' and bottom == '1' and left == '1':
                    # Check all border points: |r' - r| + |c' - c| = k
                    border_ok = True
                    for dr in range(0, k+1):
                        for dc in range(0, k+1):
                            if dr + dc == k:
                                if not ((r-dr >= 0 and r-dr < n and c-dc >= 0 and c-dc < m and grid[r-dr][c-dc] == '1') or
                                        (r-dc >= 0 and r-dc < n and c-dr >= 0 and c-dr < m and grid[r-dc][c-dr] == '1')):
                                    border_ok = False
                                    break
                        if not border_ok:
                            break

                    if border_ok:
                        if check_diagonal_no_touching(grid, r, c, k, n, m):
                            count += 1
    return count

def solution(data: str) -> str:
    lines = data.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())

    edge_data = []
    for i in range(m):
        parts = lines[i + 1].split()
        u, v, w = map(int, parts)
        edge_data.append({
            'u': u - 1,  # 0-indexed
            'v': v - 1,
            'w': w,
            'id': i
        })

    # If all edges form a spanning tree, nothing to output
    if m == n - 1:
        return ""

    # Build MST using Kruskal's algorithm
    parent = list(range(n))
    def find(i):
        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i, root_j = find(i), find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    in_mst = [False] * m
    mst_adj = [[] for _ in range(n)]

    # Sort edges by weight
    edges_sorted = sorted(edge_data, key=lambda x: x['w'])

    for edge in edges_sorted:
        u_idx = edge['id']
        if in_mst[u_idx]:
            continue

        u = edge['u']
        v = edge['v']
        w = edge['w']

        if union(u, v):
            in_mst[u_idx] = True
            mst_adj[u].append((v, w))
            mst_adj[v].append((u, w))

    # Precompute LCA and path max using BFS/DFS
    depth = [0] * n
    up = [[-1] * 20 for _ in range(n)]
    max_on_edge = [[-1] * 20 for _ in range(n)]

    # BFS for tree structure (avoids recursion depth issues)
    stack = [(0, -1, 0)]  # (node, parent, edge_weight_to_parent)
    depth[0] = 0

    order = []

    while stack:
        u, p, w = stack.pop()
        order.append(u)

        for v, wt in mst_adj[u]:
            if p != v:
                depth[v] = depth[u] + 1
                up[v][0] = u
                max_on_edge[v][0] = wt
                stack.append((v, u, wt))

    # Binary lifting table
    # Convert order to list traversal
    for i in range(1, 20):
        for u in order:
            if up[u][i - 1] != -1:
                up[u][i] = up[up[u][i - 1]][i - 1]
                max_on_edge[u][i] = max(max_on_edge[u][i - 1], max_on_edge[up[u][i - 1]][i - 1])

    # Function to find max edge weight on path between u and v in MST
    def get_max_on_path(u, v):
        max_w = 0

        # Lift u to same depth as v (if u is deeper)
        if depth[u] > depth[v]:
            diff = depth[u] - depth[v]
            for i in range(19, -1, -1):
                if (diff >> i) & 1:
                    max_w = max(max_w, max_on_edge[u][i])
                    u = up[u][i]

        # Lift both to LCA
        for i in range(19, -1, -1):
            if up[u][i] != up[v][i]:
                max_w = max(max_w, max_on_edge[u][i], max_on_edge[v][i])
                u = up[u][i]
                v = up[v][i]

        # Final step to LCA
        if u != v:
            max_w = max(max_w, max_on_edge[u][0], max_on_edge[v][0])

        return max_w

    # For each non-MST edge, compute max weight it can have and still be used
    result = []
    for edge in edge_data:
        if not in_mst[edge['id']]:
            result.append(get_max_on_path(edge['u'], edge['v']))

    return '\n'.join(map(str, result))

import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # first_epoch[j] = earliest time-step when j bananas can be achieved
    first_epoch = [-1] * (m + 1)
    # reachable = set of values that can be achieved (banana counts)
    reachable = {0}

    for i in range(1, n + 1):
        t, x_prime, y = map(int, lines[i].split())
        x = x_prime / 100000.0

        next_reachable = set()

        # From each reachable value, try applying the operation 0 to y times
        for k in reachable:
            for a in range(y + 1):
                new_k = k
                # Apply the operation 'a' times
                for _ in range(a):
                    if t == 1:
                        # Type 1: k := ceil(k + x)
                        new_k = math.ceil(new_k + x)
                    else:
                        # Type 2: k := ceil(k * x)
                        new_k = math.ceil(new_k * x)

                if new_k <= m:
                    next_reachable.add(new_k)

        # Update first_epoch and reachable for new values discovered
        for k in next_reachable:
            if first_epoch[k] == -1:
                first_epoch[k] = i

        reachable = next_reachable

    # Output: first_epoch[1], first_epoch[2], ..., first_epoch[m]
    return ' '.join(str(first_epoch[j]) for j in range(1, m + 1)) + ' \n'

def solution(n_str):
    parse = n_str.strip().split('\n')
    if len(parse) < 1:
        return "Ani\n"
    n = int(parse[0])

    monomials = []
    for i in range(1, n + 1):
        if i < len(parse):
            parts = parse[i].strip().split()
            if parts:
                a, b = int(parts[0]), int(parts[1])
                monomials.append((a, b))

    if n <= 2:
        if n == 1:
            return "Ani\n"
        # 2 terms - need to check if removing one leaves us with bounded polynomial
        # Two identical monomials allow Borna to win
        if monomials[0][0] == monomials[1][0] and monomials[0][1] == monomials[1][1]:
            return "Borna\n"
        # Otherwise, if both terms are essential (different exponents), Ani might win
        # But with only 2 terms, if one gets removed, the polynomial has just 1 term
        # Single positive coefficient polynomial can be unbounded: c*x^a*y^b -> can go to -inf
        return "Ani\n"

    # Check patterns
    # If all x values are equal, Borna wins
    all_x_equal = all(m[0] == monomials[0][0] for m in monomials)
    all_y_equal = all(m[1] == monomials[0][1] for m in monomials)
    if all_x_equal or all_y_equal:
        return "Borna\n"

    # Count monomials with a=0 (y terms plus constant)
    count_zero_a = sum(1 for m in monomials if m[0] == 0)
    # Count monomials with b=0 (x terms plus constant)  
    count_zero_b = sum(1 for m in monomials if m[1] == 0)

    if count_zero_a >= 3 or count_zero_b >= 3:
        return "Borna\n"

    # More complex criterion: check if there exists a monomial whose removal
    # leaves us with a configuration that guarantees boundedness
    # This happens if remaining monomials have only 1 distinct x-value OR only 1 distinct y-value

    def check_after_removal(idx_removed):
        remaining = monomials[:idx_removed] + monomials[idx_removed + 1:]
        if len(remaining) <= 1:
            return True  # Any single positive coefficient polynomial can be bounded
        dx_count = {}
        dy_count = {}
        for m in remaining:
            if m[0] not in dx_count:
                dx_count[m[0]] = 0
            dx_count[m[0]] += 1
            if m[1] not in dy_count:
                dy_count[m[1]] = 0
            dy_count[m[1]] += 1
        return max(dx_count.values()) == len(remaining) or max(dy_count.values()) == len(remaining)

    for i in range(n):
        if check_after_removal(i):
            # If for ANY monomial removal, Borna still wins, then Borna wins
            return "Borna\n"

    # Also check sub-cases
    # If after removing any monomial, we'd have monomials that might allow unboundedness
    other_conditions = []
    for i in range(n):
        remaining = monomials[:i] + monomials[i + 1:]
        if len(remaining) >= 2:
            # Check if remaining has structure guaranteeing boundedness
            dx_count = {}
            dy_count = {}
            for m in remaining:
                dx_count[m[0]] = dx_count.get(m[0], 0) + 1
                dy_count[m[1]] = dy_count.get(m[1], 0) + 1
            if not (max(dx_count.values()) == len(remaining) or max(dy_count.values()) == len(remaining)):
                # This removal leaves non-trivial structure - Ani's win
                return "Ani\n"

    return "Ani\n"

