        if first == 0:
            # All non-zero elements must be zeros, which means all are zeros
            # But we already checked all_zeros, so invalid
            return False

        # Find second non-zero element for ratio calculation
        second_idx = first_idx + 1
        while second_idx < n and seq[second_idx] == 0:
            second_idx += 1

