from typing import Set

def solution(input_str: str) -> str:
    """
    Solves the problem of finding maximum number of happy friends.

    The key insight is that we need to build a conflict graph where:
    - Each node represents a friend
    - An edge exists between two friends if they appear in the same segment
      (a segment is the sequence of events between two type 1 events)

    Two friends appear in the same segment if they both visit Hiasat's profile
    before any type 1 event (handle change) occurs between their visits.

    The problem then reduces to finding the Maximum Independent Set (MIS) 
    on this conflict graph.
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    events = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        event_type = parts[0]
        if event_type == '1':
            events.append((1,))
        else:
            events.append((2, parts[1]))

    # Identify segments (events between type 1 events)
    segments = []
    current_segment = []
    for event in events:
        if event[0] == 1:
            if current_segment:
                segments.append(current_segment)
                current_segment = []
        else:
            current_segment.append(event[1])

    if current_segment:
        segments.append(current_segment)

    # Map friend names to IDs (0 to num_friends-1)
    friend_to_id = {}
    num_friends = 0

    for segment in segments:
        for friend_name in segment:
            if friend_name not in friend_to_id:
                friend_to_id[friend_name] = num_friends
                num_friends += 1

    # Build conflict graph
    adj = [set() for _ in range(num_friends)]

    for segment in segments:
        friends_in_segment = [friend_to_id[name] for name in segment]
        # Add edges between all pairs of friends in the same segment
        for i in range(len(friends_in_segment)):
            for j in range(i + 1, len(friends_in_segment)):
                u, v = friends_in_segment[i], friends_in_segment[j]
                adj[u].add(v)
                adj[v].add(u)

    # Find maximum independent set using recursion with pruning
    # This is an exact algorithm with good heuristics for 40 nodes
    best = 0

    def solve(candidates: Set[int]) -> int:
        nonlocal best

        if not candidates:
            return 0

        # Pruning: if we can't beat current best with remaining candidates, stop
        if len(candidates) <= best:
            return 0

        # Pick pivot vertex with maximum degree among candidates
        # This helps maximize pruning
        pivot = max(candidates, key=lambda v: len(adj[v] & candidates))

        # Branch 1: Include pivot in IS (must exclude all neighbors of pivot)
        candidates1 = {v for v in candidates if v != pivot and v not in adj[pivot]}

        # Branch 2: Exclude pivot from IS (can include neighbors, but pivot not included)
        candidates2 = {v for v in candidates if v != pivot}

        result1 = 1 + solve(candidates1)
        result2 = solve(candidates2)

        best = max(best, max(result1, result2))
        return max(result1, result2)

    if num_friends == 0:
        return "0"

    result = solve(set(range(num_friends)))
    return str(result)


