    # Try to find k cycles with the required properties
    cycles = []
    used = [False] * (n + 1)
    found_all = False

    def find_immediate_cycle(start):
        """Find a cycle starting and ending at start using DFS"""
        stack = [(start, {start}, [start])]

        while stack:
            node, visited, path = stack.pop()

            for neighbor in adj[node]:
                if neighbor == start and len(path) >= 2:
                    # Found cycle back to start
                    if len(path) >= 3 and (len(path) % 3) != 0:
                        return path + [start]

                if neighbor not in visited:
                    new_visited = visited | {neighbor}
                    stack.append((neighbor, new_visited, path + [neighbor]))

        return None

