        if used[start]:
            continue

        cycle = find_immediate_cycle(start)
        if cycle:
            cycles.append(cycle)
            for v in cycle:
                used[v] = True

            if len(cycles) >= k:
                found_all = True
                break

    # Output cycles if we found enough
    if found_all:
        output = ["CYCLES"]
        for cycle in cycles[:k]:
            length = len(cycle) - 1
