MOD = 1000000007

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    s = lines[0].strip()
    if not s:
        return '0'

    try:
        n = int(lines[1].strip()) if len(lines) > 1 else 0
    except:
        n = 0

    queries = []
    for i in range(n):
        if 2 + i < len(lines):
            queries.append(lines[2 + i].strip())

    # dp_value[d] = the numeric value digit d transforms to (mod MOD)
    # dp_length[d] = the total length of the transformed string for digit d (mod MOD-1)
    dp_value = [0] * 10
    dp_length = [0] * 10

    # Initially, each digit transforms to itself
    for d in range(10):
        dp_value[d] = d
        dp_length[d] = 1

    # Process queries backwards
    for i in range(n - 1, -1, -1):
        query = queries[i]
        if not query:
            continue

        if "->" in query:
            parts = query.split("->", 1)
            try:
                di = int(parts[0].strip())
                ti = parts[1].strip()
            except:
                continue
        else:
            continue

        # Compute what ti becomes using already-processed transformations
        new_value = 0
        new_length_mod = 0

        for char in ti:
            if not char or not char.isdigit():
                continue
            digit = int(char)
            val = dp_value[digit]
            length = dp_length[digit]

            # When appending: new_value = old * 10^length + val
            new_value = (new_value * pow(10, length, MOD) % MOD + val) % MOD
            new_length_mod = (new_length_mod + length) % (MOD - 1)

        dp_value[di] = new_value
        dp_length[di] = new_length_mod

    # Compute final result from original string s
    result = 0

    for char in s:
        if not char or not char.isdigit():
            continue
        digit = int(char)

        val = dp_value[digit]
        length = dp_length[digit]

        # Append this transformed value to result
        if length == 0:
            continue

        result = (result * pow(10, length, MOD) % MOD + val) % MOD

    return str(result)

