import collections

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Read probabilities: prob[engineer_idx][size_idx]
    prob = []
    for i in range(n):
        prob.append(list(map(float, lines[i + 1].split()) / 1000.0))

    # expected[s][k] = expected matches for size s when bringing k T-shirts of that size
    expected = [[0.0] * (n + 1) for _ in range(m)]

    # For each size s, compute the Poisson-Binomial distribution (number of engineers fitting size s)
    # Then compute E[min(Y, k)] for each k
    for s in range(m):
        dist = [0.0] * (n + 1)
        dist[0] = 1.0

        for i in range(n):
            p = prob[i][s]
            new_dist = [0.0] * (n + 1)
            for k in range(n + 1):
                if dist[k] > 1e-12:
                    new_dist[k + 1] += dist[k] * p
                    new_dist[k] += dist[k] * (1 - p)
            dist = new_dist

        for k in range(n + 1):
            expected[s][k] = sum(dist[j] * min(j, k) for j in range(n + 1))

    # DP to find optimal allocation: dp[i][j] = max expected using sizes 0..i-1 with j shirts total
    dp = [[0.0] * (n + 1) for _ in range(m + 1)]

    for i in range(m):
        for j in range(n + 1):
            best = 0.0
            # Try allocating k shirts to size i (0 <= k <= j)
            for k in range(j + 1):
                val = dp[i][j - k] + expected[i][k]
                if val > best:
                    best = val
            dp[i + 1][j] = best

    return f"{dp[m][n]:.13f}"

