    for r in range(1, n + 1):
        curr_row_min = min_col[r]
        curr_row_max = max_col[r]

        if has_treasure[r]:
            # Calculate horizontal movement cost within the current row
            left_cost = abs(curr_row_min - prev_col)
            right_cost = abs(curr_row_max - curr_row_min)

            # Cost to traverse all treasures
            travel = max(left_cost, right_cost)

            dp += travel

            # After traversing, position is one of the boundaries
            # We need to find the optimal safe column to move through
            best_exit = min(abs(s - curr_row_max) for s in safe_cols)
            dp += best_exit
            prev_col = safe_cols[min(abs(s - curr_row_max) for s in safe_cols)]
        else:
            # No treasures in this row, just find shortest path to next safe column
            dp += min(abs(s - prev_col) for s in safe_cols)
            # Move up to next row
            dp += 1

        # Move up to the next row if not the last row
        if r < n and not has_treasure[r]:
            dp += 1

    return str(dp)

