def kmp_count(text, pattern):
    if not pattern or not text:
        return 0
    n, m = len(text), len(pattern)
    if m > n:
        return 0

    pi = [0] * m
    for i in range(1, m):
        j = pi[i-1]
        while j > 0 and text[i] != pattern[j]:
            j = pi[j-1]
        if text[i] == pattern[j]:
            j += 1
        pi[i] = j

    count = 0
    j = 0
    for i in range(n):
